arguments.content:
/* WellStream Platform — Global Styles */
:root {
  --navy: #15295A;
  --navy-deep: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #1E3A5F;
  --green: #6CC24A;
  --green-dark: #559e37;
  --gray-dark: #3C424B;
  --gray-mid: #6B7280;
  --gray-light: #9CA3AF;
  --white: #FFFFFF;
  --white-soft: #F0F4F8;
  --border: rgba(255,255,255,0.1);
  --card-bg: rgba(255,255,255,0.04);
  --card-bg-hover: rgba(255,255,255,0.08);
  --transition: 0.25s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--navy-deep);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ─── Typography ─── */
h1, h2, h3, h4, h5 { font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.1rem, 2vw, 1.4rem); }
h4 { font-size: 1.1rem; }
p { color: var(--gray-light); }
a { text-decoration: none; color: inherit; }

.label-tag {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 0.75rem;
}

.section-heading {
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 700;
  color: var(--white);
  margin-bottom: 1rem;
}

.section-desc {
  color: var(--gray-light);
  max-width: 680px;
  line-height: 1.7;
}

/* ─── Layout ─── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

section { padding: 5rem 0; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  letter-spacing: 0.02em;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
}
.btn-primary:hover { background: var(--green-dark); transform: translateY(-1px); }

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.4);
}
.btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,0.06); }

.btn-ghost {
  background: transparent;
  color: var(--green);
  padding: 0.6rem 0;
  font-size: 0.875rem;
}
.btn-ghost:hover { color: var(--green-dark); }
.btn-ghost .arrow { transition: transform var(--transition); }
.btn-ghost:hover .arrow { transform: translateX(4px); }

/* ─── Navigation ─── */
.nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  padding: 0 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.nav-logo {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}
.nav-logo span { color: var(--green); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
}

.nav-links a {
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  color: var(--gray-light);
  border-radius: 5px;
  transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }

.nav-dropdown {
  position: relative;
}

.nav-dropdown > a {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}
.nav-dropdown > a::after {
  content: '▾';
  font-size: 0.7rem;
  opacity: 0.7;
}

.dropdown-menu {
  display: none;
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.5rem;
  min-width: 200px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}

.nav-dropdown:hover .dropdown-menu,
.nav-dropdown:focus-within .dropdown-menu { display: block; }

.dropdown-menu a {
  display: block;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  color: var(--gray-light);
  border-radius: 5px;
}
.dropdown-menu a:hover { background: var(--card-bg); color: var(--white); }

.nav-cta { margin-left: 1rem; }

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0.5rem;
}
.nav-hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: all var(--transition);
}

/* ─── Hero ─── */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--navy-deep) 0%, #0f2040 50%, var(--navy-mid) 100%);
  position: relative;
  overflow: hidden;
  padding-top: 68px;
}

.hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -20%;
  left: 20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(21,41,90,0.6) 0%, transparent 70%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-content { position: relative; z-index: 1; }

.hero-label {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--green);
  font-weight: 700;
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.hero-label::before {
  content: '';
  width: 28px;
  height: 2px;
  background: var(--green);
}

.hero h1 {
  font-size: clamp(2rem, 4.5vw, 3.2rem);
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
  line-height: 1.15;
}

.hero h1 span { color: var(--green); }

.hero p {
  font-size: 1.05rem;
  color: var(--gray-light);
  max-width: 500px;
  margin-bottom: 2.5rem;
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Hero Visual */
.hero-visual {
  position: relative;
  z-index: 1;
}

.hero-diagram {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2rem;
  position: relative;
  overflow: hidden;
}

.hero-diagram::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--green), transparent);
}

.diagram-title {
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--green);
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.pillars-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.pillar-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem 1rem;
  text-align: center;
  position: relative;
}

.pillar-card::before {
  content: '';
  position: absolute;
  top: 0; left: 50%; transform: translateX(-50%);
  width: 40px;
  height: 2px;
  background: var(--green);
  border-radius: 2px;
}

.pillar-icon {
  width: 40px;
  height: 40px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  margin: 0.75rem auto 0.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
}

.pillar-card h4 {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 0.3rem;
  line-height: 1.3;
}

.pillar-card p {
  font-size: 0.72rem;
  color: var(--gray-light);
  line-height: 1.4;
}

.diagram-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  background: rgba(255,255,255,0.03);
  border-radius: 8px;
  padding: 0.75rem;
  overflow: hidden;
}

.flow-step {
  flex: 1;
  text-align: center;
  font-size: 0.65rem;
  color: var(--gray-light);
  font-weight: 600;
  padding: 0.4rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.flow-arrow {
  color: var(--green);
  font-size: 0.8rem;
  opacity: 0.5;
}

/* ─── Product Banner ─── */
.product-banner {
  background: linear-gradient(90deg, var(--navy) 0%, #1a3360 50%, var(--navy) 100%);
  padding: 1.5rem 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.product-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.product-banner-content {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

.product-badge {
  background: rgba(108,194,74,0.15);
  border: 1px solid rgba(108,194,74,0.3);
  border-radius: 8px;
  padding: 0.5rem 1rem;
  text-align: center;
}
.product-badge .badge-label { font-size: 0.65rem; color: var(--green); text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.product-badge .badge-name { font-size: 1rem; font-weight: 800; color: var(--white); }

.product-banner-text h3 { font-size: 1rem; color: var(--white); }
.product-banner-text p { font-size: 0.85rem; color: var(--gray-light); }

/* ─── Section Shared ─── */
.section-header {
  margin-bottom: 3rem;
}

.section-header.center {
  text-align: center;
}

.section-header.center .section-desc {
  margin: 0 auto;
}

/* ─── Use Cases ─── */
.use-cases { background: var(--navy-mid); }

.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  margin-bottom: 2.5rem;
}

.use-case-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem;
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.use-case-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--green);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.use-case-card:hover {
  background: var(--card-bg-hover);
  border-color: rgba(108,194,74,0.3);
  transform: translateY(-3px);
}

.use-case-card:hover::before { transform: scaleX(1); }

.use-case-icon {
  width: 44px;
  height: 44px;
  background: rgba(108,194,74,0.12);
  border-radius: 10px;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: background var(--transition);
}

.use-case-card:hover .use-case-icon { background: rgba(108,194,74,0.2); }

.use-case-card h3 {
  font-size: 0.975rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 0.5rem;
  line-height: 1.35;
}

.use-case-card p {
  font-size: 0.82rem;
  color: var(--gray-light);
  line-height: 1.6;
}

/* ─── Industry Tabs ─── */
.industry-tabs-section { background: var(--navy-deep); }

.tabs-nav {
  display: flex;
  gap: 0.25rem;
  background: rgba(255,255,255,0.04);
  border-radius: 10px;
  padding: 0.35rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.tab-btn {
  flex: 1;
  min-width: 80px;
  padding: 0.65rem 1rem;
  border: none;
  background: transparent;
  color: var(--gray-light);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 7px;
  transition: all var(--transition);
  text-align: center;
  white-space: nowrap;
}

.tab-btn.active {
  background: var(--green);
  color: var(--white);
}

.tab-btn:hover:not(.active) {
  background: rgba(255,255,255,0.06);
  color: var(--white);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.tab-content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: start;
}

.tab-content-text h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--white);
}
.tab-content-text p {
  font-size: 0.9rem;
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

.tab-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.tab-features li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.875rem;
  color: var(--gray-light);
}

.tab-features li::before {
  content: '✓';
  color: var(--green);
  font-weight: 700;
  font-size: 0.8rem;
  width: 18px;
  height: 18px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.tab-content-visual {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.75rem;
  position: relative;
}

.tab-visual-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border);
}

.dot { width: 10px; height: 10px; border-radius: 50%; }
.dot-r { background: #ff5f57; }
.dot-y { background: #febc2e; }
.dot-g { background: #28c840; }

.metric-row {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.metric-item { display: flex; flex-direction: column; gap: 0.3rem; }
.metric-label { font-size: 0.72rem; color: var(--gray-mid); text-transform: uppercase; letter-spacing: 0.06em; }
.metric-value { font-size: 1.1rem; font-weight: 700; color: var(--white); }
.metric-bar { height: 6px; background: rgba(255,255,255,0.08); border-radius: 3px; overflow: hidden; }
.metric-fill { height: 100%; background: linear-gradient(90deg, var(--green), #4fa832); border-radius: 3px; }

/* ─── Platform Overview Diagram ─── */
.platform-diagram-section { background: var(--navy-mid); }

.ecosystem-diagram {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 120px 1fr;
  gap: 0;
  align-items: center;
}

.eco-column {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.eco-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem;
  transition: all var(--transition);
}

.eco-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: var(--card-bg-hover);
}

.eco-card-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.5rem;
}

.eco-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(108,194,74,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  flex-shrink: 0;
}

.eco-card h4 { font-size: 0.85rem; color: var(--white); font-weight: 600; }
.eco-card p { font-size: 0.75rem; color: var(--gray-light); line-height: 1.5; }

.eco-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.eco-hub {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--green), #4fa832);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  position: relative;
  box-shadow: 0 0 30px rgba(108,194,74,0.3);
}
.eco-hub::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px dashed rgba(108,194,74,0.4);
  animation: spin 12s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.eco-hub-label { font-size: 0.65rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; color: rgba(255,255,255,0.8); }
.eco-hub-name { font-size: 0.75rem; font-weight: 800; color: var(--white); }

.eco-connector {
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, var(--green), transparent);
  margin: 0.25rem 0;
}

/* ─── Company Culture ─── */
.culture-section {
  background: linear-gradient(135deg, var(--navy-deep) 0%, var(--navy) 100%);
  position: relative;
  overflow: hidden;
}

.culture-section::before {
  content: '';
  position: absolute;
  top: 0; right: 0;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(108,194,74,0.06) 0%, transparent 70%);
}

.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.culture-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  margin-top: 2rem;
}

.culture-stat {
  text-align: center;
  padding: 1.5rem 1rem;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 10px;
}

.culture-stat .stat-num {
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
  display: block;
}
.culture-stat .stat-label {
  font-size: 0.75rem;
  color: var(--gray-light);
  margin-top: 0.25rem;
}

/* ─── Renewables CTA ─── */
.renewables-cta {
  background: var(--navy-mid);
  border-top: 1px solid var(--border);
}

.renewables-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2.5rem 3rem;
  position: relative;
  overflow: hidden;
}

.renewables-inner::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 4px;
  background: var(--green);
  border-radius: 4px 0 0 4px;
}

.renewables-inner h2 { font-size: 1.6rem; margin-bottom: 0.75rem; }
.renewables-inner p { max-width: 600px; }

/* ─── Footer ─── */
footer {
  background: #080e18;
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid var(--border);
}

.footer-brand .nav-logo { margin-bottom: 1rem; display: block; }
.footer-brand p { font-size: 0.85rem; color: var(--gray-mid); line-height: 1.7; max-width: 280px; }

.footer-col h5 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-mid);
  font-weight: 700;
  margin-bottom: 1rem;
}

.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-col ul li a { font-size: 0.875rem; color: var(--gray-light); transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--green); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p { font-size: 0.8rem; color: var(--gray-mid); }

.footer-portals {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.footer-portals a {
  font-size: 0.78rem;
  color: var(--gray-mid);
  padding: 0.3rem 0.75rem;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 4px;
  transition: all var(--transition);
}

.footer-portals a:hover {
  color: var(--white);
  border-color: rgba(255,255,255,0.3);
}

/* ─── Cookie Banner ─── */
.cookie-banner {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  background: var(--navy-mid);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem 1.75rem;
  max-width: 560px;
  width: calc(100% - 3rem);
  box-shadow: 0 8px 40px rgba(0,0,0,0.5);
  display: flex;
  gap: 1.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.cookie-text { flex: 1; min-width: 200px; }
.cookie-text h4 { font-size: 0.9rem; color: var(--white); margin-bottom: 0.25rem; }
.cookie-text p { font-size: 0.8rem; color: var(--gray-light); }

.cookie-actions { display: flex; gap: 0.5rem; flex-shrink: 0; }

.btn-cookie-accept {
  padding: 0.5rem 1.25rem;
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  background: var(--green);
  color: var(--white);
  transition: background var(--transition);
}
.btn-cookie-accept:hover { background: var(--green-dark); }

.btn-cookie-decline {
  padding: 0.5rem 1.25rem;
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--gray-light);
  transition: all var(--transition);
}
.btn-cookie-decline:hover { color: var(--white); border-color: rgba(255,255,255,0.3); }

/* ─── Page Hero (sub-pages) ─── */
.page-hero {
  padding: 8rem 0 5rem;
  background: linear-gradient(135deg, var(--navy-deep) 0%, var(--navy) 100%);
  position: relative;
  overflow: hidden;
}

.page-hero::after {
  content: '';
  position: absolute;
  bottom: -1px; left: 0; right: 0;
  height: 60px;
  background: linear-gradient(to top, var(--navy-mid), transparent);
}

.page-hero-content { max-width: 680px; }
.page-hero h1 { margin-bottom: 1rem; }
.page-hero p { font-size: 1.05rem; color: var(--gray-light); }

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: var(--gray-mid);
  margin-bottom: 1.5rem;
}
.breadcrumb a { color: var(--green); }
.breadcrumb .sep { opacity: 0.4; }

/* ─── Platform Benefits ─── */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1rem;
}

.benefit-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem 1.25rem;
  text-align: center;
  transition: all var(--transition);
}

.benefit-card:hover {
  border-color: rgba(108,194,74,0.3);
  transform: translateY(-3px);
}

.benefit-icon {
  width: 52px;
  height: 52px;
  background: rgba(108,194,74,0.12);
  border-radius: 50%;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
}

.benefit-card h3 {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 0.4rem;
}
.benefit-card p { font-size: 0.78rem; color: var(--gray-light); line-height: 1.6; }

/* ─── Circular Stats ─── */
.stats-section { background: var(--navy-mid); }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.stat-card {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--green), transparent);
}

.stat-circle {
  width: 140px;
  height: 140px;
  margin: 0 auto 1.5rem;
  position: relative;
}

.stat-circle svg { transform: rotate(-90deg); }
.stat-circle .track { fill: none; stroke: rgba(255,255,255,0.08); stroke-width: 8; }
.stat-circle .fill { fill: none; stroke: var(--green); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.5s ease; }

.stat-center {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}

.stat-num {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--white);
  line-height: 1;
}

.stat-unit { font-size: 0.9rem; color: var(--green); font-weight: 600; }
.stat-card h3 { font-size: 0.95rem; font-weight: 700; color: var(--white); margin-bottom: 0.4rem; }
.stat-card p { font-size: 0.82rem; color: var(--gray-light); line-height: 1.6; max-width: 220px; margin: 0 auto; }

/* ─── Implementation Timeline ─── */
.timeline-section { background: var(--navy-deep); }

.timeline-grid {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.timeline-item {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 2rem;
  align-items: center;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem;
}

.timeline-duration {
  text-align: center;
}

.timeline-duration .duration-num {
  display: block;
  font-size: 2rem;
  font-weight: 800;
  color: var(--green);
  line-height: 1;
}

.timeline-duration .duration-unit {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-mid);
  font-weight: 600;
}

.timeline-content h3 { font-size: 1rem; color: var(--white); margin-bottom: 0.75rem; }

.progress-bar {
  height: 8px;
  background: rgba(255,255,255,0.08);
  border-radius: 4px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--green), #4fa832);
  border-radius: 4px;
  transition: width 1s ease;
}

/* ─── Accordion ─── */
.accordion-section { background: var(--navy-mid); }

.accordion { display: flex; flex-direction: column; gap: 0.5rem; }

.accordion-item {
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.open {
  border-color: rgba(108,194,74,0.3);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  background: var(--card-bg);
  border: none;
  cursor: pointer;
  color: var(--white);
  font-size: 1rem;
  font-weight: 700;
  text-align: left;
  transition: background var(--transition);
}

.accordion-trigger:hover { background: var(--card-bg-hover); }
.accordion-item.open .accordion-trigger { background: rgba(108,194,74,0.08); }

.accordion-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  transition: all var(--transition);
  flex-shrink: 0;
}

.accordion-item.open .accordion-icon {
  border-color: var(--green);
  color: var(--green);
  transform: rotate(45deg);
}

.accordion-body {
  display: none;
  padding: 0 1.5rem 1.5rem;
  background: rgba(108,194,74,0.04);
}

.accordion-item.open .accordion-body { display: block; }
.accordion-body p { font-size: 0.9rem; color: var(--gray-light); line-height: 1.7; padding-top: 0.75rem; }

/* ─── Data Lifecycle Diagram ─── */
.lifecycle-diagram {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 3rem 2rem;
  overflow-x: auto;
}

.lifecycle-stages {
  display: flex;
  align-items: stretch;
  gap: 0;
  min-width: 600px;
}

.lifecycle-stage {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

.lifecycle-stage:not(:last-child)::after {
  content: '→';
  position: absolute;
  right: -12px;
  top: 30px;
  color: var(--green);
  font-size: 1.2rem;
  z-index: 1;
}

.stage-node {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--navy-light);
  border: 2px solid rgba(108,194,74,0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 0.75rem;
  position: relative;
  z-index: 1;
  transition: all var(--transition);
}

.lifecycle-stage:hover .stage-node {
  border-color: var(--green);
  background: rgba(108,194,74,0.1);
  transform: scale(1.05);
}

.stage-label { font-size: 0.75rem; font-weight: 600; color: var(--white); text-align: center; }
.stage-sub { font-size: 0.65rem; color: var(--gray-mid); text-align: center; margin-top: 0.2rem; }

/* ─── Testimonials ─── */
.testimonials-section { background: var(--navy-deep); }

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 0 0.5rem;
}

.testimonial-inner {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2.5rem;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  position: relative;
}

.testimonial-inner::before {
  content: '"';
  position: absolute;
  top: 1rem; left: 1.5rem;
  font-size: 4rem;
  color: rgba(108,194,74,0.2);
  font-family: Georgia, serif;
  line-height: 1;
}

.testimonial-text {
  font-size: 1.05rem;
  color: var(--white);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 1.5rem;
}

.testimonial-author {
  font-size: 0.85rem;
  color: var(--green);
  font-weight: 600;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  cursor: pointer;
  border: none;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--green);
  width: 24px;
  border-radius: 4px;
}

/* ─── Security ─── */
.security-tabs-section { background: var(--navy-mid); }

.security-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.security-feature-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem;
  display: flex;
  gap: 1rem;
  transition: all var(--transition);
}

.security-feature-card:hover {
  border-color: rgba(108,194,74,0.3);
  background: var(--card-bg-hover);
}

.security-icon {
  width: 48px;
  height: 48px;
  background: rgba(108,194,74,0.12);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  flex-shrink: 0;
}

.security-feature-card h3 { font-size: 0.95rem; color: var(--white); margin-bottom: 0.4rem; }
.security-feature-card p { font-size: 0.82rem; color: var(--gray-light); line-height: 1.6; }

.compliance-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.compliance-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  text-align: center;
  transition: all var(--transition);
}

.compliance-card:hover { border-color: rgba(108,194,74,0.3); }

.compliance-badge {
  width: 72px;
  height: 72px;
  background: linear-gradient(135deg, var(--green), #4fa832);
  border-radius: 50%;
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  box-shadow: 0 4px 16px rgba(108,194,74,0.3);
}

.compliance-card h3 { font-size: 1rem; color: var(--white); margin-bottom: 0.5rem; }
.compliance-card p { font-size: 0.82rem; color: var(--gray-light); line-height: 1.6; }

.compliance-cta-section { background: var(--navy-deep); }

.cta-block {
  background: linear-gradient(135deg, var(--navy) 0%, #1a3360 100%);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 4rem 3rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-block::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 0%, rgba(108,194,74,0.08) 0%, transparent 60%);
}

.cta-block h2 { position: relative; margin-bottom: 1rem; }
.cta-block p { position: relative; max-width: 540px; margin: 0 auto 2rem; }
.cta-block .btn { position: relative; }

/* ─── Integration ─── */
.integration-tabs-section { background: var(--navy-mid); }

.integration-tab-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.integration-visual {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 2rem;
}

.integration-visual h4 {
  font-size: 0.85rem;
  color: var(--gray-mid);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border);
}

.flow-diagram {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.flow-box {
  background: rgba(255,255,255,0.04);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  font-size: 0.8rem;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.flow-box.highlight {
  border-color: rgba(108,194,74,0.4);
  background: rgba(108,194,74,0.08);
}

.flow-connector {
  text-align: center;
  color: var(--green);
  font-size: 0.85rem;
  opacity: 0.7;
}

.etl-benefits-section { background: var(--navy-deep); }

.etl-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.etl-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.75rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: all var(--transition);
}

.etl-card:hover { border-color: rgba(108,194,74,0.3); background: var(--card-bg-hover); }

.etl-check {
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.etl-card h3 { font-size: 0.95rem; color: var(--white); margin-bottom: 0.4rem; }
.etl-card p { font-size: 0.82rem; color: var(--gray-light); line-height: 1.6; }

/* ─── Demo Form ─── */
.demo-section {
  background: var(--navy-deep);
  padding: 7rem 0 5rem;
}

.demo-grid {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 4rem;
  align-items: start;
}

.demo-info h1 { margin-bottom: 1.25rem; font-size: clamp(1.8rem, 4vw, 2.6rem); }
.demo-info p { margin-bottom: 2rem; line-height: 1.7; }

.demo-highlights {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.demo-highlight {
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
}

.demo-highlight-icon {
  width: 36px;
  height: 36px;
  background: rgba(108,194,74,0.12);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.demo-highlight h4 { font-size: 0.875rem; color: var(--white); margin-bottom: 0.2rem; }
.demo-highlight p { font-size: 0.8rem; color: var(--gray-light); line-height: 1.5; }

.demo-form-card {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2.5rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group.full { grid-column: 1 / -1; }

.form-group label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--gray-light);
  letter-spacing: 0.02em;
}

.form-group input,
.form-group select,
.form-group textarea {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 7px;
  padding: 0.7rem 1rem;
  color: var(--white);
  font-size: 0.875rem;
  font-family: inherit;
  transition: border-color var(--transition);
  width: 100%;
}

.form-group input::placeholder,
.form-group textarea::placeholder { color: rgba(255,255,255,0.25); }

.form-group select option { background: var(--navy-mid); color: var(--white); }

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--green);
  background: rgba(108,194,74,0.06);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #ef4444;
}

.form-group .error-msg {
  font-size: 0.75rem;
  color: #ef4444;
  display: none;
}

.form-group.has-error .error-msg { display: block; }

.form-group textarea { resize: vertical; min-height: 100px; }

.form-submit-wrap {
  margin-top: 1.5rem;
}

.form-submit-wrap .btn {
  width: 100%;
  justify-content: center;
  padding: 0.9rem 2rem;
  font-size: 1rem;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem 1rem;
}

.form-success .success-icon {
  width: 64px;
  height: 64px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
}

.form-success h3 { font-size: 1.3rem; margin-bottom: 0.75rem; }
.form-success p { font-size: 0.9rem; color: var(--gray-light); }

/* ─── Support Section ─── */
.support-section { background: var(--navy-mid); }

.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.support-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  text-align: center;
  transition: all var(--transition);
}

.support-card:hover { border-color: rgba(108,194,74,0.3); transform: translateY(-3px); }

.support-flag {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(108,194,74,0.12);
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.support-card h3 { font-size: 1rem; color: var(--white); margin-bottom: 0.4rem; }
.support-card p { font-size: 0.82rem; color: var(--gray-light); }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .benefits-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  section { padding: 3.5rem 0; }

  .nav-links, .nav-cta { display: none; }
  .nav-hamburger { display: flex; }

  .nav-mobile-open .nav-links {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: rgba(13,27,42,0.98);
    padding: 1rem;
    border-bottom: 1px solid var(--border);
    backdrop-filter: blur(12px);
  }

  .nav-mobile-open .nav-cta { display: block; margin: 0 1rem 1rem; }

  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .pillars-grid { grid-template-columns: 1fr; }

  .use-cases-grid { grid-template-columns: 1fr; }
  .culture-grid { grid-template-columns: 1fr; }
  .culture-stats { grid-template-columns: repeat(3, 1fr); }

  .renewables-inner { grid-template-columns: 1fr; padding: 2rem; }

  .footer-grid { grid-template-columns: 1fr 1fr; }

  .benefits-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: 1fr; }
  .timeline-item { grid-template-columns: 80px 1fr; gap: 1rem; }

  .security-features-grid { grid-template-columns: 1fr; }
  .compliance-grid { grid-template-columns: 1fr; }
  .integration-tab-content { grid-template-columns: 1fr; }
  .etl-grid { grid-template-columns: 1fr; }

  .demo-grid { grid-template-columns: 1fr; }
  .demo-form-card { padding: 1.5rem; }
  .form-grid { grid-template-columns: 1fr; }

  .support-grid { grid-template-columns: 1fr; }

  .tab-content-grid { grid-template-columns: 1fr; }
  .ecosystem-diagram { grid-template-columns: 1fr; }
  .eco-center { flex-direction: row; justify-content: center; }
  .eco-connector { width: 40px; height: 1px; }

  .tabs-nav { gap: 0.15rem; }
